public without sharing class ContactTriggerHandler {
    public void beforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    public void beforeUpdate(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, false);
    }

    public void afterInsert(List<Contact> newContacts) {
        applyAccountPhoneFromContacts(newContacts);
    }

    private void applyAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account parentAccount = accountsById.get(c.AccountId);
            if (parentAccount == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = parentAccount.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = parentAccount.AccountSource;
            }
        }
    }

    private void applyAccountPhoneFromContacts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account parentAccount = accountsById.get(c.AccountId);
            if (parentAccount == null || String.isNotBlank(parentAccount.Phone)) {
                continue;
            }
            // First contact in trigger order wins: later contacts see Phone already set.
            parentAccount.Phone = c.Phone;
            accountsToUpdate.put(parentAccount.Id, parentAccount);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
