public inherited sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {
    }

    private static final String CALLOUT_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final String CURRENCY_REGEX = '[A-Z]{3}';
    private static final Integer HTTP_OK = 200;
    private static final Integer HTTP_SERVICE_UNAVAILABLE = 503;

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies are required');
        }

        String base = normalizeCurrency(baseCurrency);
        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            quotes.add(normalizeCurrency(quote));
        }

        String symbols = String.join(new List<String>(quotes), ',');
        HttpResponse response = sendRequest(base, symbols);
        if (response.getStatusCode() == HTTP_SERVICE_UNAVAILABLE) {
            response = sendRequest(base, symbols);
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != HTTP_OK) {
            throw new ExchangeRateException('Unexpected HTTP status ' + statusCode);
        }

        return parseRates(response.getBody(), quotes);
    }

    private static String normalizeCurrency(String code) {
        if (code == null) {
            throw new ExchangeRateException('Invalid currency code');
        }
        String normalized = code.trim().toUpperCase();
        if (!Pattern.matches(CURRENCY_REGEX, normalized)) {
            throw new ExchangeRateException('Invalid currency code');
        }
        return normalized;
    }

    private static HttpResponse sendRequest(String base, String symbols) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(
            CALLOUT_ENDPOINT +
            '?base=' +
            EncodingUtil.urlEncode(base, 'UTF-8') +
            '&symbols=' +
            EncodingUtil.urlEncode(symbols, 'UTF-8')
        );
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return new Http().send(request);
    }

    private static Map<String, Decimal> parseRates(String body, Set<String> quotes) {
        Map<String, Object> ratesByCode;
        try {
            Map<String, Object> payload = (Map<String, Object>) JSON.deserializeUntyped(body);
            ratesByCode = (Map<String, Object>) payload.get('rates');
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response');
        }

        if (ratesByCode == null) {
            throw new ExchangeRateException('Unable to parse exchange rate response');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quotes) {
            Object rawRate = ratesByCode.get(code);
            if (rawRate == null) {
                throw new ExchangeRateException('Missing rate for ' + code);
            }
            try {
                result.put(code, toDecimal(rawRate));
            } catch (Exception e) {
                throw new ExchangeRateException('Unable to parse exchange rate response');
            }
        }
        return result;
    }

    private static Decimal toDecimal(Object rawRate) {
        if (rawRate instanceof Decimal) {
            return (Decimal) rawRate;
        }
        if (rawRate instanceof Integer) {
            return Decimal.valueOf((Integer) rawRate);
        }
        if (rawRate instanceof Long) {
            return Decimal.valueOf((Long) rawRate);
        }
        if (rawRate instanceof Double) {
            return Decimal.valueOf((Double) rawRate);
        }
        if (rawRate instanceof String) {
            return Decimal.valueOf((String) rawRate);
        }
        throw new ExchangeRateException('Unable to parse exchange rate response');
    }
}
