public class PaymentTerms {
    private static final Pattern NET_DAYS_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');

    public static Integer parseNetDays(String terms) {
        String trimmed = terms == null ? null : terms.trim();

        if (String.isNotBlank(trimmed)) {
            if (trimmed.equalsIgnoreCase('DUE ON RECEIPT')) {
                return 0;
            }

            Matcher matcher = NET_DAYS_PATTERN.matcher(trimmed);
            if (matcher.matches()) {
                Integer days = Integer.valueOf(matcher.group(1));
                if (days > 180) {
                    throw new TermsOutOfRangeException('Net days out of range: ' + days);
                }
                return days;
            }
        }

        throw new UnsupportedTermsException(
            'Unsupported payment terms: ' + (terms == null ? 'null' : terms)
        );
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        return invoiceDate.addDays(parseNetDays(terms));
    }
}
