public with sharing class RecordSearchService {
    public class SearchException extends Exception {
    }

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200 inclusive');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty');
        }
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object does not exist');
        }

        Schema.SObjectType objectType = Schema.getGlobalDescribe().get(objectApiName);
        if (objectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
        if (!objectDescribe.isAccessible() || !objectDescribe.isQueryable()) {
            throw new SearchException('Cannot read object: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        List<String> selectClause = new List<String>{ 'Id' };
        Set<String> seenSelectFields = new Set<String>{ 'Id' };
        for (String fieldName : fields) {
            Schema.DescribeFieldResult fieldDescribe = requireReadableField(fieldMap, fieldName);
            String apiName = fieldDescribe.getName();
            if (!seenSelectFields.contains(apiName)) {
                selectClause.add(apiName);
                seenSelectFields.add(apiName);
            }
        }

        Map<String, Object> binds = new Map<String, Object>();
        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String filterField : filters.keySet()) {
                Schema.DescribeFieldResult fieldDescribe = requireReadableField(fieldMap, filterField);
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + filterField);
                }
                String bindName = 'v' + bindIndex;
                conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                binds.put(bindName, filters.get(filterField));
                bindIndex++;
            }
        }

        String query =
            'SELECT ' +
            String.join(selectClause, ', ') +
            ' FROM ' +
            objectDescribe.getName();

        if (!conditions.isEmpty()) {
            query += ' WHERE ' + String.join(conditions, ' AND ');
        }

        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fieldDescribe = requireReadableField(fieldMap, orderByField);
            if (!fieldDescribe.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + orderByField);
            }
            query += ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
        }

        query += ' LIMIT ' + maxRows;

        try {
            return Database.queryWithBinds(query, binds, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException(e.getMessage(), e);
        }
    }

    private static Schema.DescribeFieldResult requireReadableField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('Field does not exist: ' + fieldName);
        }
        Schema.SObjectField token = fieldMap.get(fieldName);
        if (token == null) {
            throw new SearchException('Field does not exist: ' + fieldName);
        }
        Schema.DescribeFieldResult fieldDescribe = token.getDescribe();
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException('Cannot read field: ' + fieldName);
        }
        return fieldDescribe;
    }
}
