public with sharing class ContactLookupAction {
    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> emailsToQuery = new Set<String>();
        List<String> normalizedByRequest = new List<String>();

        for (Request request : requests) {
            String normalized = (request == null) ? null : normalize(request.email);
            normalizedByRequest.add(normalized);
            if (normalized != null) {
                emailsToQuery.add(normalized);
            }
        }

        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!emailsToQuery.isEmpty()) {
            for (Contact contact : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
                WITH USER_MODE
            ]) {
                if (String.isBlank(contact.Email)) {
                    continue;
                }
                String key = contact.Email.toLowerCase();
                if (!contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, contact.Id);
                }
            }
        }

        for (String normalized : normalizedByRequest) {
            Result result = new Result();
            Id matchedId = (normalized == null) ? null : contactIdByEmail.get(normalized);
            result.contactId = matchedId;
            result.found = matchedId != null;
            results.add(result);
        }

        return results;
    }

    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }
}
