public with sharing class AccountScoringJob implements Queueable {
    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_REVENUE = 1000000;
    private static final Decimal WARM_REVENUE = 100000;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        Integer currentSize = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> currentBatch = new List<Id>();
        for (Integer i = 0; i < currentSize; i++) {
            currentBatch.add(accountIds[i]);
        }

        rateAccounts(currentBatch);

        if (accountIds.size() <= currentSize) {
            return;
        }

        List<Id> remainingIds = new List<Id>();
        for (Integer i = currentSize; i < accountIds.size(); i++) {
            remainingIds.add(accountIds[i]);
        }

        try {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        } catch (System.AsyncException e) {
            rateAccounts(remainingIds);
        }
    }

    private void rateAccounts(List<Id> ids) {
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :ids
        ];
        for (Account account : accounts) {
            if (account.AnnualRevenue >= HOT_REVENUE) {
                account.Rating = 'Hot';
            } else if (account.AnnualRevenue >= WARM_REVENUE) {
                account.Rating = 'Warm';
            } else {
                account.Rating = 'Cold';
            }
        }
        update accounts;
    }
}
