public without sharing class ErpSyncFinalizer implements Finalizer {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = this.attempt
        );

        if (context.getResult() == ParentJobResult.SUCCESS) {
            jobLog.Status__c = 'Success';
        } else {
            jobLog.Status__c = 'Failed';
            Exception ex = context.getException();
            if (ex != null && ex.getMessage() != null) {
                String message = ex.getMessage();
                jobLog.Error__c = message.length() > 255 ? message.substring(0, 255) : message;
            }
            if (this.attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(this.accountIds, this.attempt + 1));
            }
        }

        insert jobLog;
    }
}
