/**
 * Keeps Account open-pipeline totals in sync from Opportunity DML.
 * Runs without sharing so every open Opportunity is counted, not only those
 * visible to the running user. Recursion from AccountTrigger (which updates
 * open Opportunities on every Account update) is avoided by ignoring updates
 * that do not change AccountId, Amount, or IsClosed — no static bypass flag,
 * so later DML in the same transaction is still processed.
 */
public without sharing class OpportunityPipelineHandler {
    public static void handle(List<Opportunity> newRecords, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = getAffectedAccountIds(newRecords, oldMap);
        if (accountIds.isEmpty()) {
            return;
        }
        refreshAccountTotals(accountIds);
    }

    private static Set<Id> getAffectedAccountIds(List<Opportunity> newRecords, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();

        if (oldMap == null) {
            // insert, undelete
            for (Opportunity record : newRecords) {
                addIfOpen(accountIds, record);
            }
        } else if (newRecords == null) {
            // delete
            for (Opportunity record : oldMap.values()) {
                addIfOpen(accountIds, record);
            }
        } else {
            // update: both accounts when reparenting; skip unrelated field edits
            for (Opportunity record : newRecords) {
                Opportunity prior = oldMap.get(record.Id);
                if (record.AccountId != prior.AccountId
                    || record.Amount != prior.Amount
                    || record.IsClosed != prior.IsClosed) {
                    addIfOpen(accountIds, record);
                    addIfOpen(accountIds, prior);
                }
            }
        }

        return accountIds;
    }

    private static void addIfOpen(Set<Id> accountIds, Opportunity record) {
        if (record.AccountId != null && !record.IsClosed) {
            accountIds.add(record.AccountId);
        }
    }

    private static void refreshAccountTotals(Set<Id> accountIds) {
        Map<Id, Account> accountsById = new Map<Id, Account>();
        for (Id accountId : accountIds) {
            accountsById.put(
                accountId,
                new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = 0,
                    FB_Open_Opportunities__c = 0
                )
            );
        }

        for (AggregateResult row : [
            SELECT AccountId, SUM(Amount) pipeline, COUNT(Id) oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Decimal pipeline = (Decimal) row.get('pipeline');
            Id accountId = (Id) row.get('AccountId');
            accountsById.put(
                accountId,
                new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = pipeline == null ? 0 : pipeline,
                    FB_Open_Opportunities__c = (Integer) row.get('oppCount')
                )
            );
        }

        Map<Id, Account> existingById = new Map<Id, Account>(
            [
                SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
                FROM Account
                WHERE Id IN :accountIds
            ]
        );

        List<Account> toUpdate = new List<Account>();
        for (Account calculated : accountsById.values()) {
            Account existing = existingById.get(calculated.Id);
            if (existing == null) {
                continue;
            }
            if (existing.FB_Open_Pipeline__c != calculated.FB_Open_Pipeline__c
                || existing.FB_Open_Opportunities__c != calculated.FB_Open_Opportunities__c) {
                toUpdate.add(calculated);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
