public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {
    private static final String NIGHTLY_JOB_NAME = 'Log purge (nightly)';
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';
    private static final Integer BATCH_SIZE = 2000;
    private static final Integer DEFAULT_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final String ERROR_LEVEL = 'ERROR';

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        return System.schedule(NIGHTLY_JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    public void execute(SchedulableContext sc) {
        Database.executeBatch(this, BATCH_SIZE);
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime defaultCutoff = Datetime.now().addDays(-DEFAULT_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :errorCutoff
                OR (
                    CreatedDate < :defaultCutoff
                    AND (Level__c = null OR Level__c != :ERROR_LEVEL)
                )
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        List<Database.DeleteResult> results = Database.delete(scope, false);
        List<Id> deletedIds = new List<Id>();
        for (Database.DeleteResult result : results) {
            if (result.isSuccess()) {
                deletedIds.add(result.getId());
            }
        }
        if (!deletedIds.isEmpty()) {
            Database.emptyRecycleBin(deletedIds);
        }
    }

    public void finish(Database.BatchableContext bc) {
    }
}
