public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        for (Id accountId : accountIds) {
            if (accountId != null) {
                result.put(accountId, 0);
            }
        }

        if (result.isEmpty()) {
            return result;
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :result.keySet()
            AND IsWon = true
            AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            result.put((Id) ar.get('AccountId'), totalAmount == null ? 0 : totalAmount);
        }

        return result;
    }
