        ctx.uow = (fflib_ISObjectUnitOfWork) ctx.mocks.mock(fflib_ISObjectUnitOfWork.class);
        ctx.selector = (IOpportunitiesSelector) ctx.mocks.mock(IOpportunitiesSelector.class);

        ctx.mocks.startStubbing();
        ctx.mocks.when(ctx.selector.sObjectType()).thenReturn(Opportunity.SObjectType);
        if (ids != null) {
            ctx.mocks.when(ctx.selector.selectById(ids)).thenReturn(selected);
