        );

        OpportunitiesService.OpportunitiesServiceException caught;
        try {
            OpportunitiesService.applyDiscounts(opportunityIds, discountPercentage);
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            caught = e;
        }

        Assert.isNotNull(
            caught,
            'Expected OpportunitiesServiceException for discountPercentage=' + discountPercentage
        );
        collaborators.verifyNotUsed();
    }

    private static void assertNothingAppliedOrCommitted(Set<Id> opportunityIds, Decimal discountPercentage) {
        MockCollaborators collaborators = new MockCollaborators();
        collaborators.stubAndInject(opportunityIds, new List<Opportunity>());

