    private static void assertAppliesUnchangedPercentageThenCommitsOnce(Decimal discountPercentage) {
        MockCollaborators collaborators = new MockCollaborators();
        Id opportunityId1 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id opportunityId2 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Set<Id> opportunityIds = new Set<Id>{ opportunityId1, opportunityId2 };
        List<Opportunity> selectedOpportunities = new List<Opportunity>{
            new Opportunity(Id = opportunityId1, Name = 'Opp 1', Amount = 1000),
            new Opportunity(Id = opportunityId2, Name = 'Opp 2', Amount = 2500)
        };
        collaborators.stubAndInject(opportunityIds, selectedOpportunities);

        OpportunitiesService.applyDiscounts(opportunityIds, discountPercentage);

        collaborators.verifyAppliedThenCommitted(opportunityIds, discountPercentage);
    }

    private class MockCollaborators {
        final fflib_ApexMocks mocks;
        final IOpportunities domainMock;
        final IOpportunitiesSelector selectorMock;
        final fflib_ISObjectUnitOfWork uowMock;
        final List<String> callOrder = new List<String>();

        MockCollaborators() {
            mocks = new fflib_ApexMocks();
            domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
            selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
            uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        }

        void stubAndInject(Set<Id> opportunityIds, List<Opportunity> records) {
            mocks.startStubbing();
            mocks.when(domainMock.sObjectType()).thenReturn(Opportunity.SObjectType);
            mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
            if (opportunityIds != null) {
                mocks.when(selectorMock.selectById(opportunityIds)).thenReturn(records);
            }
            ((IOpportunities) mocks.doAnswer(new CallRecorder(callOrder, 'applyDiscount'), domainMock))
                .applyDiscount(
                    (Decimal) fflib_Match.anyDecimal(),
                    (fflib_ISObjectUnitOfWork) fflib_Match.anyObject()
                );
            ((fflib_ISObjectUnitOfWork) mocks.doAnswer(new CallRecorder(callOrder, 'commitWork'), uowMock))
                .commitWork();
            mocks.stopStubbing();

            Application.Domain.setMock(domainMock);
            Application.Selector.setMock(selectorMock);
            Application.UnitOfWork.setMock(uowMock);
        }

        void verifyNotUsed() {
            ((IOpportunitiesSelector) mocks.verify(selectorMock, mocks.never()))
                .selectById((Set<Id>) fflib_Match.anyObject());
            ((IOpportunities) mocks.verify(domainMock, mocks.never()))
                .applyDiscount(
                    (Decimal) fflib_Match.anyDecimal(),
                    (fflib_ISObjectUnitOfWork) fflib_Match.anyObject()
                );
            ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).commitWork();
            Assert.areEqual(0, callOrder.size(), 'Domain and unit of work must not be used');
        }

        void verifyAppliedThenCommitted(Set<Id> opportunityIds, Decimal discountPercentage) {
            ((IOpportunitiesSelector) mocks.verify(selectorMock, mocks.times(1))).selectById(opportunityIds);
            ((IOpportunities) mocks.verify(domainMock, mocks.times(1)))
                .applyDiscount(discountPercentage, uowMock);
            ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.times(1))).commitWork();
            Assert.areEqual(
                new List<String>{ 'applyDiscount', 'commitWork' },
                callOrder,
                'applyDiscount must be called once with the unit of work, then commitWork once'
            );
        }
    }

    private class CallRecorder implements fflib_Answer {
        private final List<String> callOrder;
        private final String name;

        CallRecorder(List<String> callOrder, String name) {
            this.callOrder = callOrder;
            this.name = name;
        }

        public Object answer(fflib_InvocationOnMock invocation) {
            callOrder.add(name);
            return null;
        }
    }
}
