public inherited sharing class CaseEscalationService {
    public class EscalationException extends Exception {
    }

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason is required');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        List<Case> casesToEscalate = new List<Case>();
        List<Task> tasksToCreate = new List<Task>();

        for (Case record : cases) {
            if (record.Status == 'Closed' || record.IsEscalated) {
                continue;
            }

            record.IsEscalated = true;
            record.Priority = 'High';
            casesToEscalate.add(record);

            tasksToCreate.add(
                new Task(
                    Subject = 'Escalated: ' + reason,
                    WhatId = record.Id,
                    OwnerId = record.OwnerId,
                    ActivityDate = Date.today().addDays(1),
                    Priority = 'High'
                )
            );
        }

        if (casesToEscalate.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Case record : casesToEscalate) {
            uow.registerDirty(record);
        }

        for (Task record : tasksToCreate) {
            uow.registerNew(record);
        }

        uow.commitWork();
    }
}
