public inherited sharing class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> accounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account accountRecord = new Account(Name = accountName);
            uow.registerNew(accountRecord);
            accounts.add(accountRecord);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null || lastNames.isEmpty()) {
                continue;
            }

            for (String lastName : lastNames) {
                Contact contactRecord = new Contact(LastName = lastName);
                uow.registerNew(contactRecord, Contact.AccountId, accountRecord);
            }
        }

        uow.commitWork();
        return accounts;
    }
