public with sharing class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();
        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        List<Contact> contacts = new List<Contact>();
        for (Contact contact : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            if (String.isNotBlank(contact.Phone)) {
                contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
                contacts.add(contact);
            }
        }

        if (contacts.isEmpty()) {
            return errorsByContactId;
        }

        List<Database.SaveResult> saveResults = Database.update(contacts, false);
        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult saveResult = saveResults[i];
            if (!saveResult.isSuccess()) {
                errorsByContactId.put(
                    contacts[i].Id,
                    saveResult.getErrors()[0].getMessage()
                );
            }
        }
        return errorsByContactId;
    }
}
