public with sharing class PipelineSummary {
    private static final List<String> OPEN_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Sums Opportunity.Amount by the four managed open stages for CloseDates in [fromDate, toDate].
     * One GROUP BY query is used instead of a per-stage query in a loop: four round-trips
     * still count against governor limits and add latency, and buy no extra clarity here.
     * "No SOQL in loops" remains the production rule even when the iteration count is fixed.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>{
            'Prospecting' => 0,
            'Qualification' => 0,
            'Proposal/Price Quote' => 0,
            'Negotiation/Review' => 0
        };

        for (AggregateResult row : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :OPEN_STAGES
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            GROUP BY StageName
        ]) {
            Decimal totalAmount = (Decimal) row.get('totalAmount');
            totals.put((String) row.get('StageName'), totalAmount != null ? totalAmount : 0);
        }

        return totals;
    }
}
