/**
 * Publishes Deal_Stage_Change__e platform events for Opportunity stage changes.
 *
 * Deviation from per-record EventBus.publish in a loop:
 * EventBus.publish() counts as a DML statement (150 DML statements per transaction).
 * This method is invoked from an Opportunity trigger handler with up to 200 records,
 * so publishing inside the loop would exceed the DML limit and throw a LimitException.
 * EventBus.publish(List<SObject>) issues a single DML statement and returns
 * List<Database.SaveResult> in the same order as the input, so the caller can still
 * identify exactly which event failed by index.
 */
public inherited sharing class DealEventPublisher {
    /**
     * Publishes one Deal_Stage_Change__e per Opportunity and returns the publish
     * results in input order. An empty or null list publishes nothing and returns
     * an empty list.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opportunity : opportunities) {
            events.add(
                new Deal_Stage_Change__e(
                    Opportunity_Id__c = opportunity.Id,
                    Stage__c = opportunity.StageName,
                    Amount__c = opportunity.Amount
                )
            );
        }

        return EventBus.publish(events);
    }
}
