trigger OpportunityTrigger on Opportunity (after insert, after update) {
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        if (Trigger.isInsert) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
            continue;
        }

        Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
        Boolean stageOrAmountChanged =
            opp.StageName != oldOpp.StageName || opp.Amount != oldOpp.Amount;
        Boolean accountChanged = opp.AccountId != oldOpp.AccountId;

        if (stageOrAmountChanged || accountChanged) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
            if (accountChanged && oldOpp.AccountId != null) {
                accountIds.add(oldOpp.AccountId);
            }
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
