public with sharing class LineItemDiscountHandler {
    /**
     * Before insert: default Discount from PricingRules when the rep left it blank.
     * An explicit Discount, including 0, is left unchanged.
     *
     * Do not call PricingRules.standardDiscountFor in the line loop. That method
     * queries Product2 per Id, so CPQ inserts of up to 200 lines would exceed the
     * 100-SOQL governor limit. Product2Id is also not reliably populated on
     * OpportunityLineItem in before insert (it is derived from PricebookEntry).
     *
     * Query PricebookEntry once and call PricingRules.standardDiscountForFamily so
     * the discount percentages stay owned by PricingRules.
     *
     * Preferred follow-up: add a bulk API on PricingRules, e.g.
     * Map<Id, Decimal> standardDiscountFor(Set<Id> productIds).
     */
    public static void applyStandardDiscount(List<OpportunityLineItem> lineItems) {
        if (lineItems == null || lineItems.isEmpty()) {
            return;
        }

        Set<Id> pricebookEntryIds = new Set<Id>();
        for (OpportunityLineItem lineItem : lineItems) {
            if (lineItem.Discount == null && lineItem.PricebookEntryId != null) {
                pricebookEntryIds.add(lineItem.PricebookEntryId);
            }
        }

        if (pricebookEntryIds.isEmpty()) {
            return;
        }

        Map<Id, PricebookEntry> entriesById = new Map<Id, PricebookEntry>([
            SELECT Id, Product2Id, Product2.Family
            FROM PricebookEntry
            WHERE Id IN :pricebookEntryIds
        ]);

        for (OpportunityLineItem lineItem : lineItems) {
            if (lineItem.Discount != null) {
                continue;
            }

            PricebookEntry entry = entriesById.get(lineItem.PricebookEntryId);
            if (entry != null && entry.Product2 != null) {
                lineItem.Discount = PricingRules.standardDiscountForFamily(entry.Product2.Family);
            }
        }
    }
}
