trigger CaseTrigger on Case (after update) {
    // Collect every Case that transitioned to Closed in this transaction.
    // Contact filtering happens in the job so a Case with no Contact simply
    // creates no Task, as required.
    List<Case> newlyClosed = new List<Case>();
    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !oldCase.IsClosed) {
            newlyClosed.add(c);
        }
    }

    if (newlyClosed.isEmpty()) {
        return;
    }

    // System.enqueueJob allows at most 50 jobs per transaction (often fewer if
    // other automation already enqueued work). List-view closes and the nightly
    // API cleanup can close up to 200 Cases, so we cannot always enqueue one
    // job per Case directly. When we are within the limit we still enqueue
    // exactly as specified: one CaseSurveyJob per Case. Overflow is split into
    // parallel chains; each execute still handles a single Case so one failure
    // cannot affect the others.
    Integer available = Limits.getLimitQueueableJobs() - Limits.getQueueableJobs();
    if (available <= 0) {
        return;
    }

    if (newlyClosed.size() <= available) {
        for (Case c : newlyClosed) {
            System.enqueueJob(new CaseSurveyJob(c.Id));
        }
        return;
    }

    List<List<Id>> chains = new List<List<Id>>();
    for (Integer i = 0; i < available; i++) {
        chains.add(new List<Id>());
    }
    for (Integer i = 0; i < newlyClosed.size(); i++) {
        chains[Math.mod(i, available)].add(newlyClosed[i].Id);
    }
    for (List<Id> chain : chains) {
        System.enqueueJob(new CaseSurveyJob(chain));
    }
}
