/**
 * Asynchronous CSAT survey step for a newly closed Case.
 *
 * One Case is processed per execute so a failure on one Case cannot block
 * others. Additional Ids are supported so the trigger can stay within the
 * 50 System.enqueueJob-per-transaction limit when agents or the nightly
 * cleanup close Cases in bulk (up to 200). Database.AllowsCallouts is
 * declared now so the planned vendor integration can be added without
 * changing the job's contract.
 */
public without sharing class CaseSurveyJob implements Queueable, Database.AllowsCallouts {
    private final List<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>();
        if (caseId != null) {
            this.caseIds.add(caseId);
        }
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds == null ? new List<Id>() : new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        Id currentCaseId = caseIds.remove(0);

        // Catch so that chaining below still commits. An uncaught exception
        // would roll back enqueueJob and drop the remaining Cases.
        try {
            createSurveyTask(currentCaseId);
        } catch (Exception e) {
            System.debug(
                LoggingLevel.ERROR,
                'CaseSurveyJob failed for Case ' + currentCaseId + ': ' + e.getMessage()
            );
        }

        if (!caseIds.isEmpty()) {
            System.enqueueJob(new CaseSurveyJob(caseIds));
        }
    }

    private void createSurveyTask(Id caseId) {
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (cases.isEmpty() || cases[0].ContactId == null) {
            return;
        }

        Case closedCase = cases[0];
        Task surveyTask = new Task(
            WhatId = closedCase.Id,
            WhoId = closedCase.ContactId,
            Subject = 'CSAT survey: ' + closedCase.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );
        insert surveyTask;
    }
}
