/**
 * Syncs Contact.MailingCountry when Account.BillingCountry changes.
 *
 * Query strategy change vs. selecting every Contact into a map:
 * do NOT run [SELECT Id, AccountId, MailingCountry FROM Contact] with no filter.
 * This org has ~2.3 million contacts and MDM updates accounts in batches of 200.
 * An unfiltered Contact query would exceed the 50,000-row SOQL governor limit,
 * exhaust heap, and scan/lock far more rows than the transaction needs.
 *
 * Instead: collect accounts whose BillingCountry actually changed, then run
 * one filtered query for only those accounts' contacts. No queries in loops.
 */
public with sharing class AccountCountrySync {
    @TestVisible
    private AccountCountrySync() {
    }

    public static void syncMailingCountryFromBillingCountry(
        List<Account> newAccounts,
        Map<Id, Account> oldAccountsById
    ) {
        Map<Id, Account> changedAccountsById = new Map<Id, Account>();
        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccountsById.get(newAccount.Id);
            if (newAccount.BillingCountry != oldAccount.BillingCountry) {
                changedAccountsById.put(newAccount.Id, newAccount);
            }
        }

        if (changedAccountsById.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contactRecord : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountsById.keySet()
        ]) {
            Account newAccount = changedAccountsById.get(contactRecord.AccountId);
            Account oldAccount = oldAccountsById.get(contactRecord.AccountId);
            Boolean mailingIsBlank = String.isBlank(contactRecord.MailingCountry);
            Boolean mailingMatchesPreviousCountry =
                contactRecord.MailingCountry == oldAccount.BillingCountry;

            if (mailingIsBlank || mailingMatchesPreviousCountry) {
                if (contactRecord.MailingCountry != newAccount.BillingCountry) {
                    contactRecord.MailingCountry = newAccount.BillingCountry;
                    contactsToUpdate.add(contactRecord);
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
