import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasStats = false;

    _inFlight = false;
    _intervalId;

    connectedCallback() {
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
        if (document.visibilityState !== 'hidden') {
            this.loadStats();
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.loadStats();
            this.startPolling();
        }
    };

    startPolling() {
        this.stopPolling();
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, POLL_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId) {
            clearInterval(this._intervalId);
            this._intervalId = undefined;
        }
    }

    async loadStats() {
        if (this._inFlight || document.visibilityState === 'hidden') {
            return;
        }

        this._inFlight = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasStats = true;
            this.errorMessage = undefined;
        } catch (error) {
            this.errorMessage = error.body.message;
        } finally {
            this._inFlight = false;
        }
    }
}
