import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' ']);

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeValue;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        if (!this.isActiveInOptions()) {
            this.moveActiveToSelectedOrFirst();
        }
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        const hasChanged = this._value !== value;
        this._value = value;
        if (hasChanged) {
            this.moveActiveToSelectedOrFirst();
        }
    }

    get computedOptions() {
        return this._options.map((option, index) => ({
            id: this.optionId(index),
            value: option.value,
            label: option.label,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendantId() {
        if (this._options.length === 0) {
            return '';
        }
        return this.optionId(this.getActiveIndex());
    }

    optionId(index) {
        return `status-listbox-option-${index}`;
    }

    isActiveInOptions() {
        return this._options.some((option) => option.value === this._activeValue);
    }

    getActiveIndex() {
        const index = this._options.findIndex((option) => option.value === this._activeValue);
        return index < 0 ? 0 : index;
    }

    moveActiveToSelectedOrFirst() {
        if (this._options.length === 0) {
            this._activeValue = this._value;
            return;
        }
        const selectedIndex = this._options.findIndex((option) => option.value === this._value);
        this._activeValue =
            selectedIndex >= 0 ? this._options[selectedIndex].value : this._options[0].value;
    }

    setActiveIndex(index) {
        this._activeValue = this._options[index].value;
    }

    select(value) {
        if (this._value === value) {
            return;
        }
        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value }
            })
        );
    }

    handleKeyDown(event) {
        if (!HANDLED_KEYS.has(event.key)) {
            return;
        }
        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        const lastIndex = this._options.length - 1;
        const activeIndex = this.getActiveIndex();

        switch (event.key) {
            case 'ArrowDown':
                this.setActiveIndex(Math.min(activeIndex + 1, lastIndex));
                break;
            case 'ArrowUp':
                this.setActiveIndex(Math.max(activeIndex - 1, 0));
                break;
            case 'Home':
                this.setActiveIndex(0);
                break;
            case 'End':
                this.setActiveIndex(lastIndex);
                break;
            case 'Enter':
            case ' ':
                this.select(this._options[activeIndex].value);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const dataValue = event.currentTarget.dataset.value;
        const option = this._options.find((item) => String(item.value) === String(dataValue));
        if (!option) {
            return;
        }
        this._activeValue = option.value;
        this.select(option.value);
