import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this.items;
    }
    set tasks(value) {
        const source = Array.isArray(value) ? value : [];
        this.items = source.map((task) => ({
            id: task.id,
            label: task.label,
            done: task.done
        }));
    }

    get headingDisplay() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const input = this.template.querySelector('.new-task');
        const rawValue = input && input.value != null ? input.value : this.newLabel;
        const label = String(rawValue).trim();
        if (!label) {
            return;
        }

        this.items = [...this.items, { id: this.createId(), label, done: false }];
        this.newLabel = '';
        if (input) {
            input.value = '';
        }

        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const done = event.target.checked;
        this.items = this.items.map((task) =>
            String(task.id) === String(id) ? { ...task, done } : task
        );
    }

    createId() {
        const existing = new Set(this.items.map((task) => String(task.id)));
        let id = `new-${this.nextId++}`;
        while (existing.has(id)) {
            id = `new-${this.nextId++}`;
        }
        return id;
    }
}
