public with sharing class EmployerService {
    /**
     * Sets each Contact's current employer to the given Organization Account by
     * updating Contact.npsp__Primary_Affiliation__c. NPSP then creates a Current,
     * Primary affiliation (or reuses an existing one) and closes any previous
     * primary affiliation as Former with an end date of today. Household Account
     * membership is left unchanged.
     *
     * A null or empty map is a no-op. Contacts whose primary affiliation is already
     * the given organization are skipped so no duplicate affiliation is created.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact existing : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ]) {
            Id employerId = employerByContactId.get(existing.Id);
            if (employerId != null && existing.npsp__Primary_Affiliation__c != employerId) {
                contactsToUpdate.add(
                    new Contact(
                        Id = existing.Id,
                        npsp__Primary_Affiliation__c = employerId
                    )
                );
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
