/**
 * @description Stages one-off website gifts as NPSP Data Import records and
 * processes them synchronously through NPSP BDI so contact matching, household
 * creation, and donation processing rules apply. Staged Data Import rows remain
 * in the org as the audit trail of what was imported.
 */
public inherited sharing class GiftImportService {
    private static final String DONATION_DONOR_CONTACT1 = 'Contact1';
    private static final String STATUS_IMPORTED = 'Imported';

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    /**
     * @description Stages and synchronously processes each gift through NPSP Data Import.
     * Row-level BDI failures do not stop remaining gifts. Returns results in input order.
     * @param gifts Gifts to import; null or empty returns an empty list.
     * @return One ImportResult per input gift, in the same order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        List<npsp__DataImport__c> dataImports = stageDataImports(gifts);
        insert dataImports;

        npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getInstance();
        npsp.BDI_DataImport_API.processDataImportRecords(diSettings, dataImports, false);

        return buildResults(dataImports);
    }

    private static List<npsp__DataImport__c> stageDataImports(List<WebGift> gifts) {
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            dataImports.add(
                new npsp__DataImport__c(
                    npsp__Contact1_Firstname__c = gift.firstName,
                    npsp__Contact1_Lastname__c = gift.lastName,
                    npsp__Contact1_Personal_Email__c = gift.email,
                    npsp__Donation_Amount__c = gift.amount,
                    npsp__Donation_Date__c = gift.giftDate,
                    npsp__Donation_Donor__c = DONATION_DONOR_CONTACT1
                )
            );
        }
        return dataImports;
    }

    private static List<ImportResult> buildResults(List<npsp__DataImport__c> dataImports) {
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
            SELECT
                npsp__Status__c,
                npsp__Contact1Imported__c,
                npsp__DonationImported__c,
                npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImports
        ]);

        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c staged : dataImports) {
            npsp__DataImport__c processed = processedById.get(staged.Id);
            ImportResult result = new ImportResult();
            result.success = processed.npsp__Status__c == STATUS_IMPORTED;
            result.contactId = processed.npsp__Contact1Imported__c;
            result.opportunityId = processed.npsp__DonationImported__c;
            result.errorMessage = processed.npsp__FailureInformation__c;
            results.add(result);
        }
        return results;
    }
}
