/**
 * Replaces Opportunity-level GAU Allocations by percentage.
 * Only npsp__Percent__c is set so NPSP recalculates npsp__Amount__c
 * whenever Opportunity.Amount changes.
 */
public with sharing class GauAllocationService {
    public class AllocationException extends Exception {
    }

    /**
     * Replaces all Opportunity-level GAU Allocations for the given Opportunity
     * with one percent-based allocation per map entry.
     *
     * @param opportunityId Opportunity to allocate
     * @param percentByGauId GAU Id -> percent (60 means 60%)
     * @return the inserted allocations
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        validatePercents(percentByGauId);
        validateGausAreActive(percentByGauId.keySet());

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
                AND npsp__Payment__c = null
                AND npsp__Campaign__c = null
                AND npsp__Recurring_Donation__c = null
            WITH USER_MODE
        ];

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(
                new npsp__Allocation__c(
                    npsp__Opportunity__c = opportunityId,
                    npsp__General_Accounting_Unit__c = gauId,
                    npsp__Percent__c = percentByGauId.get(gauId)
                )
            );
        }

        Savepoint sp = Database.setSavepoint();
        try {
            if (!existingAllocations.isEmpty()) {
                Database.delete(existingAllocations, AccessLevel.USER_MODE);
            }
            Database.insert(newAllocations, AccessLevel.USER_MODE);
        } catch (DmlException e) {
            Database.rollback(sp);
            throw e;
        }

        return newAllocations;
    }

    private static void validatePercents(Map<Id, Decimal> percentByGauId) {
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percentage map cannot be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Decimal percent : percentByGauId.values()) {
            if (percent == null || percent <= 0) {
                throw new AllocationException('Each percentage must be greater than 0.');
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Percentages cannot add up to more than 100.');
        }
    }

    private static void validateGausAreActive(Set<Id> gauIds) {
        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
                WITH USER_MODE
            ]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null || gau.npsp__Active__c != true) {
                throw new AllocationException('All General Accounting Units must be active.');
            }
        }
    }
}
