/**
 * Creates NPSP Household Accounts and associates member Contacts with them.
 */
public with sharing class HouseholdService {
    /**
     * Inserts the given new Contacts so they all belong to one new NPSP
     * Household Account. The first Contact is the household primary contact.
     * Account naming and greetings are left to NPSP automatic household naming.
     *
     * @param members New Contact records (no Id, no AccountId)
     * @return Id of the Household Account
     * @throws IllegalArgumentException if members is null or empty
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members cannot be null or empty');
        }

        // Inserting a Contact without AccountId lets NPSP create a true
        // Household Account (HH_Account), including name and greetings.
        Contact primary = members[0];
        insert primary;

        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primary.Id
        ].AccountId;

        List<Contact> remaining = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            members[i].AccountId = householdId;
            remaining.add(members[i]);
        }
        if (!remaining.isEmpty()) {
            insert remaining;
        }

        update new Account(
            Id = householdId,
            npe01__One2OneContact__c = primary.Id
        );

        return householdId;
    }
}
