public class SoftCreditService {
    public class SoftCreditException extends Exception {
    }

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> requestedKeys = new Set<String>();

        for (SoftCreditRequest request : requests) {
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
            requestedKeys.add(toKey(request.opportunityId, request.contactId));
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [
                SELECT Id, Amount, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ]
        );

        for (SoftCreditRequest request : requests) {
            Opportunity opportunity = opportunitiesById.get(request.opportunityId);
            if (opportunity == null) {
                throw new SoftCreditException('Opportunity not found.');
            }
            if (request.contactId == opportunity.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Cannot add a partial soft credit for the opportunity primary contact.'
                );
            }
            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive.');
            }
            if (opportunity.Amount != null && request.amount > opportunity.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount cannot exceed the opportunity amount.'
                );
            }
        }

        Map<String, OpportunityContactRole> ocrByKey = new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> extraOcrsToDelete = new List<OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds AND ContactId IN :contactIds
        ]) {
            String compositeKey = toKey(ocr.OpportunityId, ocr.ContactId);
            if (!requestedKeys.contains(compositeKey)) {
                continue;
            }
            if (ocrByKey.containsKey(compositeKey)) {
                extraOcrsToDelete.add(ocr);
            } else {
                ocrByKey.put(compositeKey, ocr);
            }
        }

        Map<String, npsp__Partial_Soft_Credit__c> pscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT
                Id,
                npsp__Opportunity__c,
                npsp__Contact__c,
                npsp__Amount__c,
                npsp__Role_Name__c,
                npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds AND npsp__Contact__c IN :contactIds
        ]) {
            String compositeKey = toKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!requestedKeys.contains(compositeKey)) {
                continue;
            }
            if (!pscByKey.containsKey(compositeKey)) {
                pscByKey.put(compositeKey, psc);
            }
        }

        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        for (SoftCreditRequest request : requests) {
            String compositeKey = toKey(request.opportunityId, request.contactId);
            OpportunityContactRole ocr = ocrByKey.get(compositeKey);
            if (ocr == null) {
                ocr = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
                ocrsToUpsert.add(ocr);
                ocrByKey.put(compositeKey, ocr);
            } else if (ocr.Role != request.role) {
                ocr.Role = request.role;
                ocrsToUpsert.add(ocr);
            }
        }

        if (!extraOcrsToDelete.isEmpty()) {
            delete extraOcrsToDelete;
        }
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest request : requests) {
            String compositeKey = toKey(request.opportunityId, request.contactId);
            OpportunityContactRole ocr = ocrByKey.get(compositeKey);
            npsp__Partial_Soft_Credit__c psc = pscByKey.get(compositeKey);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId
                );
            }
            psc.npsp__Amount__c = request.amount;
            psc.npsp__Role_Name__c = request.role;
            psc.npsp__Contact_Role_ID__c = ocr.Id;
            pscsToUpsert.add(psc);
        }

        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
    }

    private static String toKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }
}
