/**
 * Records received gifts (Closed Won donations) the way NPSP expects
 * for the Household Account model with NPSP Payments enabled.
 */
public with sharing class GiftService {
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a Closed Won donation from the given contact and returns the Opportunity Id.
     * Throws IllegalArgumentException if the contact does not exist or amount is null/not positive.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }

        Contact donor = queryDonor(contactId);
        Opportunity gift = insertGift(donor, amount, giftDate);
        syncContactRoles(gift.Id, donor);
        syncPayment(gift.Id, amount, giftDate);
        return gift.Id;
    }

    private static Contact queryDonor(Id contactId) {
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        return donors[0];
    }

    private static Opportunity insertGift(Contact donor, Decimal amount, Date giftDate) {
        Opportunity gift = new Opportunity(
            Name = buildOpportunityName(donor, giftDate),
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            npe01__Do_Not_Automatically_Create_Payment__c = true
        );
        insert gift;
        return gift;
    }

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String firstName = donor.FirstName == null ? '' : donor.FirstName;
        String lastName = donor.LastName == null ? '' : donor.LastName;
        return (firstName + ' ' + lastName).trim() + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * Ensures the donor has a single Donor (primary) role, every other household
     * member has a single Household Member role, and no contact has duplicate roles.
     * Reconciles against OCRs that NPSP may have auto-created on insert.
     */
    private static void syncContactRoles(Id opportunityId, Contact donor) {
        Map<Id, String> desiredRoleByContactId = new Map<Id, String>();
        desiredRoleByContactId.put(donor.Id, ROLE_DONOR);

        if (donor.AccountId != null) {
            for (Contact member : [
                SELECT Id
                FROM Contact
                WHERE AccountId = :donor.AccountId
            ]) {
                if (member.Id != donor.Id) {
                    desiredRoleByContactId.put(member.Id, ROLE_HOUSEHOLD_MEMBER);
                }
            }
        }

        Map<Id, List<OpportunityContactRole>> existingByContactId =
            new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ]) {
            if (!existingByContactId.containsKey(ocr.ContactId)) {
                existingByContactId.put(ocr.ContactId, new List<OpportunityContactRole>());
            }
            existingByContactId.get(ocr.ContactId).add(ocr);
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();

        for (Id memberId : desiredRoleByContactId.keySet()) {
            String desiredRole = desiredRoleByContactId.get(memberId);
            Boolean isPrimary = memberId == donor.Id;
            List<OpportunityContactRole> existing = existingByContactId.get(memberId);

            if (existing == null || existing.isEmpty()) {
                toInsert.add(
                    new OpportunityContactRole(
                        OpportunityId = opportunityId,
                        ContactId = memberId,
                        Role = desiredRole,
                        IsPrimary = isPrimary
                    )
                );
            } else {
                OpportunityContactRole keeper = existing[0];
                if (keeper.Role != desiredRole || keeper.IsPrimary != isPrimary) {
                    keeper.Role = desiredRole;
                    keeper.IsPrimary = isPrimary;
                    toUpdate.add(keeper);
                }
                for (Integer i = 1; i < existing.size(); i++) {
                    toDelete.add(existing[i]);
                }
            }
        }

        for (Id contactId : existingByContactId.keySet()) {
            if (desiredRoleByContactId.containsKey(contactId)) {
                continue;
            }
            List<OpportunityContactRole> extras = existingByContactId.get(contactId);
            for (Integer i = 1; i < extras.size(); i++) {
                toDelete.add(extras[i]);
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Ensures the gift has exactly one paid payment for the full amount on giftDate.
     * Reconciles against payments NPSP may have auto-created.
     */
    private static void syncPayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        npe01__OppPayment__c keeper = payments[0];
        if (
            keeper.npe01__Payment_Amount__c != amount ||
            keeper.npe01__Payment_Date__c != giftDate ||
            keeper.npe01__Scheduled_Date__c != giftDate ||
            keeper.npe01__Paid__c != true
        ) {
            keeper.npe01__Payment_Amount__c = amount;
            keeper.npe01__Payment_Date__c = giftDate;
            keeper.npe01__Scheduled_Date__c = giftDate;
            keeper.npe01__Paid__c = true;
            update keeper;
        }

        if (payments.size() > 1) {
            List<npe01__OppPayment__c> duplicates = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < payments.size(); i++) {
                duplicates.add(payments[i]);
            }
            delete duplicates;
        }
    }
}
