```apex
/**
 * @description Links imported family Contacts as NPSP Parent/Child relationships.
 * Inserts the Parent-side record (child -> parent, Type = Parent, Status = Current)
 * and lets NPSP List Setting reciprocal processing create the matching
 * Son/Daughter/Child record on the parent.
 */
public without sharing class FamilyService {
    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * @description Creates Current Parent relationships for each child-parent pair.
     * Skips pairs that already have any relationship in either direction so the
     * import is idempotent. Null or empty input is a no-op.
     * @param parentIdByChildId Child Contact Id -> parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null) {
                contactIds.add(childId);
                contactIds.add(parentId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c relationship : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
                AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairs.add(pairKey(relationship.npe4__Contact__c, relationship.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            String key = pairKey(childId, parentId);
            if (existingPairs.contains(key)) {
                continue;
            }
            existingPairs.add(key);
            toInsert.add(
                new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = TYPE_PARENT,
                    npe4__Status__c = STATUS_CURRENT
                )
            );
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * @description Undirected pair key so A-B and B-A are treated as the same pair.
     * Uses 15-char Ids so 15- and 18-char arguments match.
     */
    private static String pairKey(Id firstId, Id secondId) {
        String a = String.valueOf(firstId).left(15);
        String b = String.valueOf(secondId).left(15);
        return a < b ? a + '-' + b : b + '-' + a;
    }
}
