/**
 * TDTM handler that creates a high-priority follow-up Task when an Opportunity
 * becomes a major gift (Closed Won and Amount >= 5000).
 *
 * Register under NPSP Settings > Trigger Configuration:
 * Class: OPP_MajorGiftFollowUp_TDTM, Object: Opportunity,
 * Trigger Action: AfterInsert;AfterUpdate, Load Order: 5, Asynchronous: false.
 *
 * Deactivating that Trigger Handler record stops this class from running.
 * No standalone Apex trigger is used; NPSP's TDTM dispatcher invokes this class.
 */
global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer FOLLOW_UP_DAYS = 3;

    /**
     * Called by NPSP TDTM. Creates at most one follow-up Task per Opportunity
     * that newly qualifies as a major gift. Bulk-safe for 200 records with
     * 0 SOQL and 0 DML of its own (inserts are returned via DmlWrapper).
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        List<Opportunity> newOpps = (List<Opportunity>) newlist;
        List<Opportunity> oldOpps = (List<Opportunity>) oldlist;
        Boolean isInsert = triggerAction == npsp.TDTM_Runnable.Action.AfterInsert;

        for (Integer i = 0; i < newOpps.size(); i++) {
            Opportunity newOpp = newOpps[i];
            if (!isMajorGift(newOpp)) {
                continue;
            }
            // Updates of a gift that already qualified must not create another task
            if (!isInsert && isMajorGift(oldOpps[i])) {
                continue;
            }
            dmlWrapper.objectsToInsert.add(buildFollowUpTask(newOpp));
        }

        return dmlWrapper;
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp.StageName == STAGE_CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = opp.CloseDate == null ? null : opp.CloseDate.addDays(FOLLOW_UP_DAYS)
        );
    }
}
