```apex
public with sharing class RecordAccessService {
    /**
     * UserRecordAccess accepts at most 200 RecordIds per query.
     * 2,000 IDs therefore use 10 SOQL queries (method budget: 20).
     */
    private static final Integer ACCESS_QUERY_CHUNK_SIZE = 200;

    /**
     * Returns the subset of {@code recordIds} the running user can edit,
     * as reported by UserRecordAccess.HasEditAccess.
     * A null or empty input returns an empty set (never null).
     * IDs may belong to different objects.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        List<Id> candidateIds = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                candidateIds.add(recordId);
            }
        }
        if (candidateIds.isEmpty()) {
            return editable;
        }

        Id userId = UserInfo.getUserId();
        Integer total = candidateIds.size();
        // Bounded loop: required by the 200-Id UserRecordAccess limit, not unbounded SOQL-in-a-loop.
        for (Integer offset = 0; offset < total; offset += ACCESS_QUERY_CHUNK_SIZE) {
            Integer last = Math.min(offset + ACCESS_QUERY_CHUNK_SIZE, total);
            List<Id> chunk = new List<Id>();
            for (Integer i = offset; i < last; i++) {
                chunk.add(candidateIds[i]);
            }

            for (UserRecordAccess accessRecord : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :userId
                    AND RecordId IN :chunk
            ]) {
                if (accessRecord.HasEditAccess == true) {
                    editable.add(accessRecord.RecordId);
                }
            }
        }
        return editable;
    }
}
