public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        preventDuplicateEmails((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        preventDuplicateEmails(
            (List<Contact>) triggerNew,
            new Map<Id, Contact>((List<Contact>) triggerOld)
        );
    }

    private void preventDuplicateEmails(List<Contact> newContacts, Map<Id, Contact> oldMap) {
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> selfIds = new Set<Id>();

        for (Contact newContact : newContacts) {
            if (newContact.AccountId == null || String.isBlank(newContact.Email)) {
                continue;
            }
            if (oldMap != null) {
                Contact oldContact = oldMap.get(newContact.Id);
                if (newContact.AccountId == oldContact.AccountId && newContact.Email == oldContact.Email) {
                    continue;
                }
                selfIds.add(newContact.Id);
            }
            toCheck.add(newContact);
            accountIds.add(newContact.AccountId);
            emails.add(newContact.Email);
        }

        if (toCheck.isEmpty()) {
            return;
        }

        Map<Id, Set<String>> emailsByAccountId = new Map<Id, Set<String>>();
        for (Id accountId : accountIds) {
            emailsByAccountId.put(accountId, new Set<String>());
        }

        for (Contact existing : queryExisting(accountIds, emails, selfIds)) {
            if (String.isNotBlank(existing.Email)) {
                emailsByAccountId.get(existing.AccountId).add(existing.Email.toLowerCase());
            }
        }

        for (Contact newContact : toCheck) {
            Set<String> emailsOnAccount = emailsByAccountId.get(newContact.AccountId);
            String emailKey = newContact.Email.toLowerCase();
            if (emailsOnAccount.contains(emailKey)) {
                newContact.addError(ERROR_MESSAGE);
            } else {
                emailsOnAccount.add(emailKey);
            }
        }
    }

    private List<Contact> queryExisting(Set<Id> accountIds, Set<String> emails, Set<Id> selfIds) {
        if (selfIds.isEmpty()) {
            return [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds AND Email IN :emails
            ];
        }
        return [
            SELECT AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails AND Id NOT IN :selfIds
        ];
    }
}
